{"code": "
import sys

def sum_of_digits(n):
    """Calculate the sum of digits of a number."""
    return sum(int(d) for d in str(n))

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    t = int(data[0])
    index = 1

    for _ in range(t):
        digit = int(data[index])
        exponent = int(data[index + 1])
        index += 2

        result = digit ** exponent
        digit_sum = sum_of_digits(result)

        print(f"{result} {digit_sum}")

if __name__ == "__main__":
    main()
"}

