# Precompute prefix GCD arrays
prefix_gcd = [0] * (n + 1)
for i in range(1, n + 1):
    prefix_gcd[i] = gcd(prefix_gcd[i - 1], strengths[i - 1])

# Precompute suffix GCD arrays
suffix_gcd = [0] * (n + 1)
for i in range(n, 0, -1):
    suffix_gcd[i] = gcd(suffix_gcd[i + 1], strengths[i - 1])

# Function to compute GCD of a range [l, r]
def range_gcd(l, r):
    return gcd(prefix_gcd[l - 1], suffix_gcd[r + 1])

# Process queries
for _ in range(t):
    l, r = map(int, input().split())
    target = range_gcd(l, r)
    # Count occurrences of target in range [l, r]
count = 0
for i in range(l - 1, r):
    if strengths[i] == target:
        count += 1

    # Print result
print(r - l + 1 - count)

