import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    while idx < len(data):
        n = int(data[idx])
        idx += 1

        if n == 0:
            break

        # Build adjacency list
        adj = [[] for _ in range(101)]  # nodes are 1-indexed
        for _ in range(n):
            a = int(data[idx])
            b = int(data[idx + 1])
            idx += 2
            adj[a].append(b)
            adj[b].append(a)

        # Dynamic programming with bitmask
        max_nodes = 101
        dp = [[0] * max_nodes for _ in range(1 << max_nodes)]

        # Initialize: path of length 1 starting at each node
        for u in range(1, max_nodes):
            dp[1 << u][u] = 1

        # Try all masks
        for mask in range(1 << max_nodes):
            for u in range(1, max_nodes):
                if not (mask & (1 << u)):
                    continue

                # Try to extend the path from u
                for v in adj[u]:
                    if mask & (1 << v):
                        continue

                    new_mask = mask | (1 << v)
                    dp[new_mask][v] = max(dp[new_mask][v], dp[mask][u] + 1)

        # Find the maximum chain length
        full_mask = (1 << max_nodes) - 1
        max_len = 0
        for u in range(1, max_nodes):
            max_len = max(max_len, dp[full_mask][u])

        print(max_len)

if __name__ == "__main__":
    solve()
