import sys

def solve():
    t = int(sys.stdin.readline())

    for _ in range(t):
        # Place queen at (1, 1)
        print("1 1")
        sys.stdout.flush()

        queen_x, queen_y = 1, 1

        # We'll try to move the queen right along the first row
        for move_num in range(130):
            # Read king's move direction
            direction = sys.stdin.readline().strip()

            if direction == "Done":
                break

            # Determine new king position based on direction
            if direction == "Left":
                king_x, king_y = queen_x, queen_y - 1
            elif direction == "Right":
                king_x, king_y = queen_x, queen_y + 1
            elif direction == "Up":
                king_x, king_y = queen_x - 1, queen_y
            elif direction == "Down":
                king_x, king_y = queen_x + 1, queen_y
            elif direction == "Down-Right":
                king_x, king_y = queen_x + 1, queen_y + 1
            elif direction == "Down-Left":
                king_x, king_y = queen_x + 1, queen_y - 1
            elif direction == "Up-Left":
                king_x, king_y = queen_x - 1, queen_y - 1
            elif direction == "Up-Right":
                king_x, king_y = queen_x - 1, queen_y + 1
            else:
                # Shouldn't happen
                break

            # Move queen to the right along the first row
            if queen_y < 8:
                queen_y += 1
                print(f"1 {queen_y}")
                sys.stdout.flush()
            else:
                # Queen is at (1, 8), can't move right
                break

if __name__ == "__main__":
    solve()
