    """Return the minimum excludant of a set of integers."""
    i = 0
    while i in s:
        i += 1
    return i

def grundy(m, k, memo):
    """Return the Grundy number for a log of length m with minimum part length k."""
    if m in memo:
        return memo[m]

    # Find all valid splits
    valid = set()
    for t in range(2, m + 1):
        if m % t == 0:
            part_length = m // t
            if part_length >= k:
                # Check if t is odd
                if t % 2 == 1:
                    valid.add(grundy(part_length, k, memo))

    # Compute mex
    g = mex(valid)
    memo[m] = g
    return g

