import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    N = int(data[0])
    T = int(data[1])

    dishes = []
    idx = 2
    for _ in range(N):
        A = int(data[idx])
        B = int(data[idx + 1])
        dishes.append((A, B))
        idx += 2

    # dp[s][m] = max deliciousness for subsets with sum s and max A_i = m
    max_sum = T + 1  # We might need to go up to T + max(A_i)
    dp = [[-1] * (N + 1) for _ in range(max_sum + 1)]

    # Initialize: empty set
    dp[0][0] = 0

    for A, B in dishes:
        for s in range(max_sum, -1, -1):
            for m in range(N + 1):
                if dp[s][m] == -1:
                    continue

                # Option 1: don't take this dish
                # Option 2: take this dish
                new_s = s + A
                new_m = max(m, A)
                if new_s <= max_sum:
                    dp[new_s][new_m] = max(dp[new_s][new_m], dp[s][m] + B)

    # Find the best subset
    best = 0
    for s in range(max_sum + 1):
        for m in range(N + 1):
            if dp[s][m] == -1:
                continue
            if s - m <= T - 1:
                best = max(best, dp[s][m])

    print(best)

if __name__ == "__main__":
    solve()
