import sys

def is_valid_integer(word):
    """Check if a word is a valid nonnegative integer without leading zeroes"""
    if not word:
        return False  # Empty words are not valid integers

    # Check if word is all digits
    if not word.isdigit():
        return False

    # Check for leading zeroes
    if len(word) > 1 and word[0] == '0':
        return False

    return True

def main():
    s = sys.stdin.read().strip()

    # Split into words by commas and semicolons
    words = s.split(',')

    # Process each word
    a_words = []
    b_words = []

    for word in words:
        # Split by semicolons within this word
        sub_words = word.split(';')

        for sub_word in sub_words:
            if is_valid_integer(sub_word):
                a_words.append(sub_word)
            else:
                b_words.append(sub_word)

    # Build output strings
    a = ','.join(a_words)
    b = ','.join(b_words)

    # Handle special cases
    if not a_words:
        a = '-'
    if not b_words:
        b = '-'

    print(f"{a}")
    print(f"{b}")

if __name__ == "__main__":
    main()
