import sys

def solve():
    data = sys.stdin.read().strip().split('\n')
    t = int(data[0])
    idx = 1

    for _ in range(t):
        # Read k and protein values
        # Handle potential extra spaces
        while idx < len(data) and data[idx].strip() == "":
            idx += 1
        if idx >= len(data):
            break

        parts = data[idx].split()
        k = int(parts[0])
        protein = list(map(int, parts[1:1+k]))
        idx += 1

        # Read ingredient string
        while idx < len(data) and data[idx].strip() == "":
            idx += 1
        if idx >= len(data):
            break

        L = data[idx].strip()
        idx += 1

        # Read target sum
        while idx < len(data) and data[idx].strip() == "":
            idx += 1
        if idx >= len(data):
            break

        S = int(data[idx].strip())
        idx += 1

        # DP: dp[sum] = lexicographically smallest subsequence for that sum
        dp = {0: ""}

        for char in L:
            # Get the protein value for this character
            pos = ord(char) - ord('a')
            val = protein[pos]

            # Create a new DP table for this character
            new_dp = {}

            # Copy existing entries
            for s, seq in dp.items():
                # Option 1: skip this character
                if s not in new_dp or seq < new_dp[s]:
                    new_dp[s] = seq

                # Option 2: take this character (if it doesn't exceed the target)
                if s + val <= S:
                    new_seq = seq + char
                    if (s + val) not in new_dp or new_seq < new_dp[s + val]:
                        new_dp[s + val] = new_seq

            dp = new_dp

        # Check if we can reach the target sum
        if S in dp:
            print(dp[S])
        else:
            print("IMPOSSIBLE")

if __name__ == "__main__":
    solve()
