t = int(input())
for _ in range(t):
    n = int(input())
    a = list(map(int, input().split()))

    # Count evens and odds
    evens = sum(1 for x in a if x % 2 == 0)
    odds = n - evens

    # Check if we can achieve an alternating pattern
    if n % 2 == 0:
        # Need exactly n/2 evens and n/2 odds
        if evens != n // 2:
            print(-1)
            continue
    else:
        # Need (n+1)//2 of one parity and n//2 of the other
        if evens != (n + 1) // 2 and evens != n // 2:
            print(-1)
            continue

    # Determine the target pattern
    if n % 2 == 0:
        # Alternating starting with odd
        target = [1 if i % 2 == 0 else 0 for i in range(n)]
    else:
        # Alternating starting with odd (evens = (n+1)//2)
        if evens == (n + 1) // 2:
            target = [1 if i % 2 == 0 else 0 for i in range(n)]
        else:
            # Alternating starting with even
            target = [0 if i % 2 == 0 else 1 for i in range(n)]

    # Count how many elements are already in the correct position
    correct = 0
    for i in range(n):
        if a[i] % 2 == target[i]:
            correct += 1

    # Minimal swaps = total elements - correct positions
    print(n - correct)
