n = int(input())

# Build adjacency list
adj = [[] for _ in range(n + 1)]
for _ in range(n - 1):
    a, b = map(int, input().split())
    adj[a].append(b)
    adj[b].append(a)

# Iterative post-order traversal
stack = [(1, False)]  # (node, visited)
expected = [0.0] * (n + 1)

while stack:
    node, visited = stack.pop()
    if not visited:
        stack.append((node, True))
        # Push children (excluding parent) in reverse order for post-order
        # We need to track parent to avoid revisiting
        parent = -1
        for neighbor in adj[node]:
            if neighbor != parent:
                parent = neighbor
                stack.append((neighbor, False))
    else:
        # Calculate expected steps for this node
        expected[node] = 1.0
        for neighbor in adj[node]:
            if neighbor != parent:
                expected[node] += expected[neighbor]

print(f"{expected[1]:.20f}")
"}

