N = int(input())

# Track each participant's points over time
participants = {}
# Track when each participant reached each point total
point_times = {}

for round_num in range(N):
    line = input().strip()
    name, points = line.split()
    points = int(points)

    # Update the participant's points
    if name not in participants:
        participants[name] = points
    else:
        participants[name] += points

    # Record when this participant reached this point total
    if name not in point_times:
        point_times[name] = {}

    # We need to track when they reached this exact point total
    # But we also need to know when they reached at least m points
    # So we'll track when they reached each point total
    point_times[name][participants[name]] = round_num + 1  # 1-indexed

# Find the maximum points at the end
max_points = max(participants.values())

# For each participant with max points, find when they first reached at least max points
first_to_reach_max = None
for name in participants:
    if participants[name] == max_points:
        # Find the first round they reached at least max points
        first_round = None
        for point_total in sorted(point_times[name].keys()):
            if point_total >= max_points:
                first_round = point_times[name][point_total]
                break

        if first_round is not None:
            if first_to_reach_max is None or first_round < first_to_reach_max:
                first_to_reach_max = first_round
                winner = name

print(winner)
