import sys

def shortest_common_supersequence(strings):
    n = len(strings)

    # Precompute shortest common supersequence lengths for all pairs
    sccs = [[0] * n for _ in range(n)]

    for i in range(n):
        for j in range(n):
            if i == j:
                sccs[i][j] = len(strings[i])
            else:
                # Compute shortest common supersequence of strings[i] and strings[j]
                # This is a classic DP problem
                m, k = len(strings[i]), len(strings[j])
                dp = [[0] * (k + 1) for _ in range(m + 1)]

                for a in range(m + 1):
                    for b in range(k + 1):
                        if a == 0:
                            dp[a][b] = b
                        elif b == 0:
                            dp[a][b] = a
                        elif strings[i][a - 1] == strings[j][b - 1]:
                            dp[a][b] = dp[a - 1][b - 1] + 1
                        else:
                            dp[a][b] = min(dp[a - 1][b], dp[a][b - 1]) + 1

                sccs[i][j] = dp[m][k]

    # DP with bitmask
    dp = [float('inf')] * (1 << n)
    dp[0] = 0

    for mask in range(1 << n):
        for i in range(n):
            if not (mask & (1 << i)):
                # Try adding string i
                new_mask = mask | (1 << i)

                # Find the best way to add string i to the current supersequence
                best = float('inf')
                for j in range(n):
                    if mask & (1 << j):
                        # We already have string j in the supersequence
                        # Find the shortest supersequence of the current supersequence and string i
                        # This is the SCCS of the current supersequence and string i
                        # But we don't have the actual string, just the length
                        # So we need to track the SCCS lengths
                        best = min(best, sccs[j][i])

                dp[new_mask] = min(dp[new_mask], dp[mask] + len(strings[i]) - best)

    return dp[(1 << n) - 1]

def solve():
    while True:
        line = sys.stdin.readline()
        if not line:
            break
        n = int(line.strip())
        if n == 0:
            break

        strings = []
        for _ in range(n):
            strings.append(sys.stdin.readline().strip())

        result = shortest_common_supersequence(strings)
        print(result)

if __name__ == "__main__":
    solve()
"}

