n, k = map(int, input().split())
a = list(map(int, input().split()))

# Count of distinct elements in current window
distinct_count = 0
# Frequency map of elements in current window
freq = {}

l = 0
result = -1

for r in range(n):
    # Add element at index r to the window
    if a[r] not in freq or freq[a[r]] == 0:
        distinct_count += 1
    freq[a[r]] = freq.get(a[r], 0) + 1

    # If we have more than k distinct elements, shrink from left
    while distinct_count > k:
        freq[a[l]] -= 1
        if freq[a[l]] == 0:
            distinct_count -= 1
        l += 1

    # If we have exactly k distinct elements, check minimality
    if distinct_count == k:
        # Check if we can shrink from left
        can_shrink_left = False
        if l > 0 and freq[a[l]] > 1:
            freq[a[l]] -= 1
            if freq[a[l]] == 0:
                distinct_count -= 1
            can_shrink_left = True
            freq[a[l]] += 1  # restore

        # Check if we can shrink from right
        can_shrink_right = False
        if r < n - 1 and freq[a[r]] > 1:
            freq[a[r]] -= 1
            if freq[a[r]] == 0:
                distinct_count -= 1
            can_shrink_right = True
            freq[a[r]] += 1  # restore

        if not can_shrink_left and not can_shrink_right:
            result = (l + 1, r + 1)  # convert to 1-indexed
            break

if result == -1:
    print("-1 -1")
else:
    print(result[0], result[1])
