t = int(input())
for _ in range(t):
    a, b, c, m = map(int, input().split())

    # Maximum possible adjacent equal pairs
    max_pairs = min(a, b, c) * 2 - 1

    # Minimum possible adjacent equal pairs
    if a == 0 and b == 0 and c == 0:
        min_pairs = 0
    elif a == 0 or b == 0 or c == 0:
        # At least one letter is missing, can't have any adjacent pairs
        min_pairs = 0
    else:
        # Check if we can alternate
        max_count = max(a, b, c)
        other_sum = a + b + c - max_count

        if max_count <= other_sum + 1:
            # We can alternate perfectly
            min_pairs = 0
        else:
            # We need at least some adjacent pairs
            min_pairs = max_count - other_sum - 1

    if m > max_pairs or m < min_pairs:
        print("NO")
    else:
        print("YES")
"}

