import sys

def is_k_beautiful(num: int, k: int) -> bool:
    """Check if a number is k-beautiful"""
    digits = set(str(num))
    return len(digits) <= k

def find_min_k_beautiful(n: int, k: int) -> int:
    """Find the minimum k-beautiful number ≥ n"""
    num = n
    while True:
        if is_k_beautiful(num, k):
            return num
        num += 1

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    t = int(data[0])
    index = 1

    for _ in range(t):
        n = int(data[index])
        k = int(data[index + 1])
        index += 2

        result = find_min_k_beautiful(n, k)
        print(result)

if __name__ == "__main__":
    main()
"}

